    // ── LIFECYCLE ──
    protected override async Task OnInitializedAsync()
    {
        maTruongBo     = await BrowserStorageService.GetMaTruongBoAsync(JSRuntime);
        selectedNamHoc = await BrowserStorageService.GetItem(JS, "selectedNamHoc");
        selectedCapHoc = await BrowserStorageService.GetItem(JS, "selectedLevel");
        tenTruong      = await BrowserStorageService.GetItem(JS, "tenTruong") ?? "Trường học";

        await Task.WhenAll(LoadData(), LoadHocKy());
    }

    // ── LOAD MÔN HỌC ──
    private async Task LoadData()
    {
        if (string.IsNullOrEmpty(maTruongBo)) return;

        isLoading = true;
        StateHasChanged();

        try
        {
            AllMonHoc = await DaoTaoService.hGetMonHoc(maTruongBo);
            ApplyFilter();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"LoadData error: {ex.Message}");
            await ShowToast("Lỗi tải danh sách môn học!", "error");
        }
        finally
        {
            isLoading = false;
            StateHasChanged();
        }
    }

    // ── LOAD HỌC KỲ ──
    private async Task LoadHocKy()
    {
        if (string.IsNullOrEmpty(selectedNamHoc)) return;

        isLoadingHocKy = true;
        StateHasChanged();

        try
        {
            HocKyList = await TruongService.hGetDanhSachHocKy(selectedNamHoc);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"LoadHocKy error: {ex.Message}");
            await ShowToast("Lỗi tải danh sách học kỳ!", "error");
        }
        finally
        {
            isLoadingHocKy = false;
            StateHasChanged();
        }
    }

    // ── FILTER ──
    private void ApplyFilter()
    {
        if (AllMonHoc == null) { FilteredMonHoc = new(); DisplayMonHoc = new(); StateHasChanged(); return; }

        var result = AllMonHoc.AsEnumerable();

        if (filterTrangThai >= 0)
            result = result.Where(m => (m.trangthai ? 1 : 0) == filterTrangThai);

        if (filterHienThiDiem >= 0)
        {
            string f = filterHienThiDiem == 1 ? "1" : "0";
            result = result.Where(m => m.ishienthidiem == f);
        }

        if (!string.IsNullOrWhiteSpace(searchMonHoc))
        {
            var t = searchMonHoc.Trim();
            result = result.Where(m =>
                m.ten_mon_hoc?.Contains(t, StringComparison.OrdinalIgnoreCase) == true ||
                m.idmonhocso?.Contains(t, StringComparison.OrdinalIgnoreCase) == true);
        }

        FilteredMonHoc = result
            .OrderBy(m => !m.trangthai)
            .ThenBy(m => m.ten_mon_hoc)
            .ToList();

        currentPage = 1;
        BuildPagedList();
        StateHasChanged();
    }

    private void BuildPagedList()
    {
        DisplayMonHoc = FilteredMonHoc
            .Skip((currentPage - 1) * pageSize)
            .Take(pageSize)
            .ToList();
    }

    // ── PAGINATION ──
    private void OnPageChanged(int page)
    {
        currentPage = page;
        BuildPagedList();
        StateHasChanged();
    }

    private void OnPageSizeChanged(int size)
    {
        pageSize    = size;
        currentPage = 1;
        BuildPagedList();
        StateHasChanged();
    }

    // ── MODAL MÔN HỌC ──
    private void OpenAddMonHoc()
    {
        _editingMonHoc     = null;
        _formTenMonHoc     = "";
        _formIsHienThiDiem = "1";
        _formSoCotDgTx     = 4;
        _formTrangThai     = true;
        _showMonHocModal   = true;
    }

    private void OpenEditMonHoc(DaoTaoData.MonHocDTO item)
    {
        _editingMonHoc     = item;
        _formTenMonHoc     = item.ten_mon_hoc ?? "";
        _formIsHienThiDiem = item.ishienthidiem ?? "1";
        _formSoCotDgTx     = item.socotdgtx;
        _formTrangThai     = item.trangthai;
        _showMonHocModal   = true;
    }

    private void CloseMonHocModal()
    {
        _showMonHocModal = false;
        _editingMonHoc   = null;
    }

    private async Task SaveMonHoc()
    {
        if (string.IsNullOrWhiteSpace(_formTenMonHoc)) return;

        _isProcessing = true;
        StateHasChanged();

        try
        {
            // Cập nhật local (chưa có API write → cập nhật UI tạm thời)
            if (_editingMonHoc != null)
            {
                _editingMonHoc.ten_mon_hoc    = _formTenMonHoc.Trim();
                _editingMonHoc.ishienthidiem  = _formIsHienThiDiem;
                _editingMonHoc.socotdgtx      = _formSoCotDgTx;
                _editingMonHoc.trangthai      = _formTrangThai;
                await ShowToast("Cập nhật môn học thành công!", "success");
            }
            else
            {
                await ShowToast("Chức năng thêm mới cần API — dữ liệu chưa được lưu!", "warning");
            }

            ApplyFilter();
            CloseMonHocModal();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"SaveMonHoc error: {ex.Message}");
            await ShowToast("Lỗi lưu môn học!", "error");
        }
        finally
        {
            _isProcessing = false;
            StateHasChanged();
        }
    }

